CREATE TABLE CPF_CACHE_INVALIDATION_VERSION (
    CONSUMER_ID VARCHAR(180) NOT NULL,
    TENANT_ID VARCHAR(180) NOT NULL,
    NAMESPACE_NAME VARCHAR(180) NOT NULL,
    CACHE_KEY_VALUE VARCHAR(512) NOT NULL,
    LAST_VERSION BIGINT NOT NULL CHECK (LAST_VERSION >= 0),
    UPDATED_AT TIMESTAMP(6) WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (CONSUMER_ID, TENANT_ID, NAMESPACE_NAME, CACHE_KEY_VALUE)
);
